import{_ as t,o,c as u,a5 as d}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"常用注解","description":"","frontmatter":{"title":"常用注解","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/常用注解.md","filePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/常用注解.md"}'),s={name:"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/常用注解.md"};function r(c,e,p,l,i,n){return o(),u("div",null,[...e[0]||(e[0]=[d('<div><p><code>RequestParam</code><strong>作用：</strong> 把请求中指定名称的参数给控制器中的形参赋值。 <strong>属性：</strong></p><ul><li><code>value</code>：请求参数中的名称。</li><li><code>required</code>：请求参数中是否必须提供此参数。默认值：<code>true</code>。表示必须提供，如果不提供将报错。</li></ul><p><strong>使用示例</strong><code>jsp</code> <strong>中的代码：</strong></p><p>&lt;a href=&quot;springmvc/useRequestParam?name=test&quot;&gt;requestParam 注解</p><p><code>\\&lt;/a\\&gt;</code><strong>控制器中的代码：</strong></p><p>/**</p><ul><li>requestParams 注解的使用</li></ul><p>*/ @RequestMapping(&quot;/useRequestParam&quot;) public String useRequestParam( @RequestParam(&quot;name&quot;) String username, @RequestParam(value=&quot;age&quot;,required=false) Integer age){ System.out.println(username+&quot;,&quot;+age); return &quot;success&quot;; }</p><p><code>RequestBody</code> **作用：**用于获取请求体内容。直接使用得到是 <code>key=value&amp;key=value...</code>结构的数据。<code>get</code> 请求方式不适用。 <strong>属性：</strong></p><p><code>required</code></p><p>：是否必须有请求体。默认值是<code>:true</code>。当取值为 <code>true</code> 时<code>,get</code> 请求方式会报错。如果取值为 <code>false</code>，<code>get</code> 请求得到是 <code>null</code>。</p><p><strong>使用示例</strong><code>post</code> <strong>请求</strong> <code>jsp</code> <strong>代码：</strong></p><p>&lt;form action=&quot;springmvc/useRequestBody&quot; method=&quot;post&quot;&gt; 用户名称：</p><p><code>\\&lt;input type=&quot;text&quot; name=&quot;username&quot; \\&gt;\\&lt;br/\\&gt;</code> 用户密码：</p><p><code>\\&lt;input type=&quot;password&quot; name=&quot;password&quot; \\&gt;\\&lt;br/\\&gt;</code> 用户年龄：</p><ul><li>&lt;input type=&quot;text&quot; name=&quot;age&quot; &gt;&lt;br/&gt;</li><li>&lt;input type=&quot;submit&quot; value=&quot;</li></ul><p><em>保存</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li><li>get</li></ul><p><strong>请求</strong> <code>jsp</code> <strong>代码：</strong></p><p>&lt;a href=&quot;springmvc/useRequestBody?body=test&quot;&gt;requestBody 注解 <code>get</code> 请求</p><p><code>\\&lt;/a\\&gt;</code></p><p><strong>控制器代码：</strong></p><p><code>* RequestBody</code></p><p>注解</p><p>*/ @RequestMapping(&quot;/useRequestBody&quot;) public String useRequestBody(@RequestBody(required=false) String body){ System.out.println(body); return &quot;success&quot;; } post <strong>请求运行结果：</strong></p><p><code>PathVaribale</code><strong>作用：</strong> 用于绑定</p><p><code>url</code></p><p>中的占位符。例如：请求 <code>url</code> 中</p><p>/delete/{id} ，这个<code>{id}</code>就是 <code>url</code> 占位符。</p><p><code>url</code></p><p>支持占位符是 <code>spring3.0</code> 之后加入的，是 <code>springmvc</code>支持<code>rest</code>风格 <code>URL</code>的一个重要标志。 <strong>属性：</strong></p><p><code>value</code></p><p>：用于指定 <code>url</code> 中占位符名称。</p><p><code>required</code></p><p>：是否必须提供占位符。</p><p><strong>使用示例</strong><code>jsp</code> <strong>代码：</strong></p><p>&lt;a href=&quot;springmvc/usePathVariable/100&quot;&gt;pathVariable 注解</p><p><code>\\&lt;/a\\&gt;</code><strong>控制器代码：</strong></p><p>/**</p><ul><li>PathVariable 注解</li></ul><p>*/ @RequestMapping(&quot;/usePathVariable/{id}&quot;) public String usePathVariable(@PathVariable(&quot;id&quot;) Integer id){ System.out.println(id); return &quot;success&quot;; }</p><p><code>REST</code> <strong>风格</strong> <code>URL</code><strong>什么是</strong></p><p><code>rest</code></p><p><strong>：</strong></p><p><code>REST</code></p><p>（英文：<code>Representational State Transfer</code>，简称 <code>REST</code>）描述了一个架构样式的网络系统，比如 <code>web</code> 应用程序。它首次出现在 <code>2000</code> 年 <code>Roy Fielding</code> 的博士论文中，他是 <code>HTTP</code> 规范的主要编写者之一。在目前主流的三种 <code>Web</code> 服务交互方案中，<code>REST</code> 相比于 <code>SOAP</code>（<code>Simple Object Access protocol</code>，简单对象访问协议）以及 <code>XML-RPC</code> 更加简单明了，无论是对 <code>URL</code> 的处理还是对 <code>Payload</code> 的编码，<code>REST</code> 都倾向于用更加简单轻量的方法设计和实现。值得注意的是 <code>REST</code> 并没有一个明确的标准，而更像是一种设计的风格。 它本身并没有什么实用性，其核心价值在于如何设计出符合</p><p><code>REST</code></p><p>风格的网络接口。</p><p><code>restful</code> <strong>的优点</strong> 它结构清晰、符合标准、易于理解、扩展方便，所以正得到越来越多网站的采用。</p><p><code>restful</code> <strong>的特性：</strong> 资源（<code>Resources</code>）：网络上的一个实体，或者说是网络上的一个具体信息。 它可以是一段文本、一张图片、一首歌曲、一种服务，总之就是一个具体的存在。可以用一个 <code>URI</code>（统一资源定位符）指向它，每种资源对应一个特定的 <code>URI</code> 。要获取这个资源，访问它的 <code>URI</code> 就可以，因此 <code>URI</code> 即为每一个资源的独一无二的识别符。 表现层（<code>Representation</code>）：把资源具体呈现出来的形式，叫做它的表现层（<code>Representation</code>）。比如，文本可以用 <code>txt</code> 格式表现，也可以用 <code>HTML</code> 格式、<code>XML</code> 格式、<code>JSON</code> 格式表现，甚至可以采用二进制格式。 状态转化（<code>State Transfer</code>）：每发出一个请求，就代表了客户端和服务器的一次交互过程。 <code>HTTP</code> 协议，是一个无状态协议，即所有的状态都保存在服务器端。因此，如果客户端想要操作服务器，必须通过某种手段，让服务器端发生**“<strong>状态转化</strong>”**（<code>State Transfer</code>）。而这种转化是建立在表现层之上的，所以就是 <strong>“<strong>表现层状态转化</strong>”</strong>。具体说，就是 <code>HTTP</code> 协议里面，四个表示操作方式的动词：<code>GET</code> 、<code>POST</code> 、<code>PUT</code>、 <code>DELETE</code>。它们分别对应四种基本操作：<code>GET</code> 用来获取资源，<code>POST</code> 用来新建资源，<code>PUT</code> 用来更新资源，<code>DELETE</code> 用来删除资源。</p><p><code>restful</code> <strong>的示例：</strong></p><p><code>/account/1 HTTP GET</code></p><p>： 得到 <code>id = 1</code> 的</p><ul><li>account</li><li>/account/1 HTTP DELETE</li></ul><p>： 删除 <code>id = 1</code> 的</p><ul><li>account</li><li>/account/1 HTTP PUT</li></ul><p>： 更新 <code>id = 1</code> 的 <code>account</code> ￼</p><p><code>/account HTTP POST</code></p><p>： 新增 <code>account</code></p><p><strong>基于</strong> <code>HiddentHttpMethodFilter</code> <strong>的示例</strong><strong>作用：</strong> 由于浏览器 <code>form</code> 表单只支持 <code>GET</code> 与 <code>POST</code> 请求，而 <code>DELETE</code>、<code>PUT</code> 等 <code>method</code> 并不支持，<code>Spring3.0</code> 添 加了一个过滤器，可以将浏览器请求改为指定的请求方式，发送给我们的控制器方法，使得支持 <code>GET</code>、<code>POST</code>、<code>PUT</code>与 <code>DELETE</code> 请求。</p><p><strong>使用方法：</strong> 第一步：在 <code>web.xml</code> 中配置该过滤器。 第二步：请求方式必须使用 <code>post</code> 请求。 第三步：按照要求提供<code>_method</code> 请求参数，该参数的取值就是我们需要的请求方式。 <strong>源码分析：</strong></p><p><code>jsp</code> <strong>中示例代码：</strong></p><p>&lt;form action=&quot;springmvc/testRestPOST&quot; method=&quot;post&quot;&gt; 用户名称：</p><p>&lt;input type=&quot;text&quot; name=&quot;username&quot;&gt;&lt;br/&gt; &lt;!-- &lt;input type=&quot;hidden&quot; name=&quot;_method&quot; value=&quot;POST&quot;&gt; --&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>保存</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li><li>&lt;hr/&gt;</li><li>&lt;!--</li></ul><p>更新</p><p>--&gt; &lt;form action=&quot;springmvc/testRestPUT/1&quot; method=&quot;post&quot;&gt; 用户名称：</p><ul><li>&lt;input type=&quot;text&quot; name=&quot;username&quot;&gt;&lt;br/&gt;</li><li>&lt;input type=&quot;hidden&quot; name=&quot;_method&quot; value=&quot;PUT&quot;&gt;</li><li>&lt;input type=&quot;submit&quot; value=&quot;</li></ul><p><em>更新</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li><li>&lt;!--</li></ul><p>删除</p><p>--&gt; &lt;form action=&quot;springmvc/testRestDELETE/1&quot; method=&quot;post&quot;&gt; &lt;input type=&quot;hidden&quot; name=&quot;_method&quot; value=&quot;DELETE&quot;&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>删除</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li><li>&lt;hr/&gt;</li><li>&lt;!--</li></ul><p>查询一个</p><p>--&gt; &lt;form action=&quot;springmvc/testRestGET/1&quot; method=&quot;post&quot;&gt; &lt;input type=&quot;hidden&quot; name=&quot;_method&quot; value=&quot;GET&quot;&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>查询</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li></ul><p><strong>控制器中示例代码：</strong></p><p>/**</p><ul><li>post 请求：保存</li></ul><p><em>/ @RequestMapping(value=&quot;/testRestPOST&quot;,method=RequestMethod.POST) public String testRestfulURLPOST(User user){ System.out.println(&quot;rest post&quot;+user); return &quot;success&quot;; } /</em>*</p><ul><li>put 请求：更新</li></ul><p><em>/ @RequestMapping(value=&quot;/testRestPUT/{id}&quot;,method=RequestMethod.PUT) public String testRestfulURLPUT(@PathVariable(&quot;id&quot;)Integer id,User user){ System.out.println(&quot;rest put &quot;+id+&quot;,&quot;+user); return &quot;success&quot;; } /</em>*</p><ul><li><p>post 请求：删除</p></li><li><p>@param username</p></li><li><p>@return <em>/ @RequestMapping(value=&quot;/testRestDELETE/{id}&quot;,method=RequestMethod.DELETE) public String testRestfulURLDELETE(@PathVariable(&quot;id&quot;)Integer id){ System.out.println(&quot;rest delete &quot;+id); return &quot;success&quot;; } /</em>*</p></li><li><p>post 请求：查询</p></li><li><p>@param username</p></li><li><p>@return */ @RequestMapping(value=&quot;/testRestGET/{id}&quot;,method=RequestMethod.GET) public String testRestfulURLGET(@PathVariable(&quot;id&quot;)Integer id){ System.out.println(&quot;rest get &quot;+id); return &quot;success&quot;; } <strong>运行结果：</strong></p></li></ul><ul><li>4.4RequestHeader</li><li>4.4.1</li></ul><p><strong>使用说明</strong><strong>作用：</strong> 用于获取请求消息头。 <strong>属性：</strong></p><p><code>value</code></p><p>：提供消息头名称</p><p><code>required</code></p><p>：是否必须有此消息头 <strong>注：</strong> 在实际开发中一般不怎么用。传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 4.4.2 <code>**使用示例**</code></p><p>jsp <code>**中代码：**</code></p><p>&lt;!-- RequestHeader <code>注解</code> --&gt; &lt;a href=&quot;springmvc/useRequestHeader&quot;&gt; <code>获取请求消息头</code> &lt;/a&gt; <code>**控制器中代码：**</code></p><p>/**</p><ul><li><p>RequestHeader <code>注解</code></p></li><li><p>@param user</p></li><li><p>@return */ @RequestMapping(&quot;/useRequestHeader&quot;) public String useRequestHeader(@RequestHeader(value=&quot;Accept-Language&quot;, required=false)String requestHeader){ System.out.println(requestHeader); return &quot;success&quot;; } <code>**运行结果：**</code></p></li></ul><p>4.5CookieValue 4.5.1</p><ul><li><strong>使用说明</strong></li><li><strong>作用：</strong></li><li>用于把指定</li><li><code>cookie</code></li><li>名称的值传入控制器方法参数。</li><li><strong>属性：</strong></li></ul><p>value <code>：指定 </code>cookie<code> 的名称。</code></p><p>required <code>：是否必须有此 </code>cookie<code>。</code></p><p>4.5.2 <code>**使用示例**</code></p><p>jsp <code>**中的代码：**</code></p><p>&lt;!-- CookieValue <code>注解</code> --&gt; &lt;a href=&quot;springmvc/useCookieValue&quot;&gt; <code>绑定 </code>cookie<code> 的值</code> &lt;/a&gt; <code>**控制器中的代码：**</code></p><p>/**</p><ul><li>传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训</li><li><ul><li>Cookie</li></ul></li></ul><p>注解注解</p><ul><li>@param user</li><li>@return */ @RequestMapping(&quot;/useCookieValue&quot;) public String useCookieValue(@CookieValue(value=&quot;JSESSIONID&quot;,required=false) String cookieValue){ System.out.println(cookieValue); return &quot;success&quot;; } <strong>运行结果：</strong></li></ul><ul><li>4.6ModelAttribute</li><li>4.6.1</li></ul><p><strong>使用说明</strong><strong>作用：</strong> 该注解是</p><p><code>SpringMVC4.3</code></p><p>版本以后新加入的。它可以用于修饰方法和参数。 出现在方法上，表示当前方法会在控制器的方法执行之前，先执行。它可以修饰没有返回值的方法，也可 以修饰有具体返回值的方法。 出现在参数上，获取指定的数据给参数赋值。 <strong>属性：</strong></p><p><code>value</code></p><p>：用于获取数据的 <code>key</code>。<code>key</code> 可以是 <code>POJO</code> 的属性名称，也可以是 <code>map</code> 结构的 <code>key</code>。 <strong>应用场景：</strong> 当表单提交数据不是完整的实体类数据时，保证没有提交数据的字段使用数据库对象原来的数据。 例如： 我们在编辑一个用户时，用户有一个创建信息字段，该字段的值是不允许被修改的。在提交表单数 据是肯定没有此字段的内容，一旦更新会把该字段内容置为</p><p><code>null</code></p><p>，此时就可以使用此注解解决问题。</p><p><code>4.6.2</code></p><p><strong>使用示例</strong></p><p><code>4.6.2.1</code></p><p><strong>基于</strong> <code>POJO</code> <strong>属性的基本使用：</strong></p><p><code>jps</code></p><p><strong>代码：</strong></p><p><code>\\&lt;!-- ModelAttribute</code></p><p>注解的基本使用 <code>--\\&gt;</code>传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 &lt;a href=&quot;springmvc/testModelAttribute?username=test&quot;&gt; <code>测试</code> modelattribute&lt;/a&gt; <code>**控制器代码：**</code></p><p>/** * <code>被 </code>ModelAttribute<code> 修饰的方法</code></p><ul><li>@param user <em>/ @ModelAttribute public void showModel(User user) { System.out.println(&quot; <code>执行了 </code>showModel<code> 方法</code> &quot;+user.getUsername()); } /</em>*</li><li></li></ul><p><code>接收请求的方法</code></p><ul><li>@param user</li><li>@return */ @RequestMapping(&quot;/testModelAttribute&quot;) public String testModelAttribute(User user) { System.out.println(&quot; <code>执行了控制器的方法</code> &quot;+user.getUsername()); return &quot;success&quot;; } <code>**运行结果：**</code></li></ul><p>4.6.2.2 <strong>基于</strong> <code>Map</code> <strong>的应用场景示例</strong> <code>1</code><strong>：</strong><code>ModelAttribute</code> <strong>修饰方法带返回值</strong><strong>需求：</strong><strong>修改用户信息，要求用户的密码不能修改</strong></p><p>jsp <code>**的代码：**</code></p><p>&lt;!-- <code>修改用户信息</code> --&gt; &lt;form action=&quot;springmvc/updateUser&quot; method=&quot;post&quot;&gt; <code>用户名称：</code> &lt;input type=&quot;text&quot; name=&quot;username&quot; &gt;&lt;br/&gt; <code>用户年龄：</code> &lt;input type=&quot;text&quot; name=&quot;age&quot; &gt;&lt;br/&gt; &lt;input type=&quot;submit&quot; value=&quot; <code>_保存_</code> &quot;&gt; &lt;/form&gt; <code>**控制的代码：**</code></p><p>/** * <code>查询数据库中用户信息</code></p><ul><li>@param user */ 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 @ModelAttribute public User showModel(String username) { // 模拟去数据库查询</li></ul><p>User abc = findUserByName(username); System.out.println(&quot; 执行了 <code>showModel</code> 方法</p><p>&quot;+abc); return abc; } /** * 模拟修改用户方法</p><ul><li>@param user</li><li>@return */ @RequestMapping(&quot;/updateUser&quot;) public String testModelAttribute(User user) { System.out.println(&quot; 控制器中处理请求的方法：修改用户：</li></ul><p>&quot;+user); return &quot;success&quot;; } /** * 模拟去数据库查询</p><ul><li>@param username</li><li>@return */ private User findUserByName(String username) { User user = new User(); user.setUsername(username); user.setAge(19); user.setPassword(&quot;123456&quot;); return user; } <strong>运行结果：<strong>传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 4.6.2.3 <strong>基于</strong> <code>Map</code> <strong>的应用场景示例</strong> <code>1</code></strong>：</strong><code>ModelAttribute</code> <strong>修饰方法不带返回值</strong><strong>需求</strong>： <strong>修改用户信息，要求用户的密码不能修改</strong></li></ul><p>jsp <code>**中的代码：**</code></p><p>&lt;!-- <code>修改用户信息</code> --&gt; &lt;form action=&quot;springmvc/updateUser&quot; method=&quot;post&quot;&gt; <code>用户名称：</code> &lt;input type=&quot;text&quot; name=&quot;username&quot; &gt;&lt;br/&gt; <code>用户年龄：</code> &lt;input type=&quot;text&quot; name=&quot;age&quot; &gt;&lt;br/&gt; &lt;input type=&quot;submit&quot; value=&quot; <code>_保存_</code> &quot;&gt; &lt;/form&gt; <code>**控制器中的代码：**</code></p><p>/** * <code>查询数据库中用户信息</code></p><ul><li>@param user */ @ModelAttribute public void showModel(String username,Map&lt;String,User&gt; map) { // <code>模拟去数据库查询</code></li></ul><p>User user = findUserByName(username); System.out.println(&quot; <code>执行了 </code>showModel<code> 方法</code> &quot;+user); map.put(&quot;abc&quot;,user); } /** * <code>模拟修改用户方法</code></p><ul><li>@param user</li><li>@return <em>/ @RequestMapping(&quot;/updateUser&quot;) public String testModelAttribute(@ModelAttribute(&quot;abc&quot;)User user) { System.out.println(&quot; <code>控制器中处理请求的方法：修改用户：</code> &quot;+user); return &quot;success&quot;; } /</em>*</li><li></li></ul><p><code>模拟去数据库查询</code></p><ul><li>@param username</li><li>@return */ private User findUserByName(String username) { User user = new User(); user.setUsername(username); 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 user.setAge(19); user.setPassword(&quot;123456&quot;); return user; } <strong>运行结果：</strong></li></ul><ul><li>4.7SessionAttribute</li><li>4.7.1</li></ul><p><strong>使用说明</strong><strong>作用：</strong> 用于多次执行控制器方法间的参数共享。 <strong>属性：</strong></p><p><code>value</code></p><p>：用于指定存入的属性名称</p><p><code>type</code></p><p>：用于指定存入的数据类型。</p><p><code>4.7.2</code></p><p><strong>使用示例</strong></p><p><code>jsp</code></p><p><strong>中的代码：</strong></p><p><code>\\&lt;!-- SessionAttribute</code></p><p>注解的使用</p><ul><li>--&gt;</li><li>&lt;a href=&quot;springmvc/testPut&quot;&gt;</li></ul><p>存入</p><ul><li>SessionAttribute&lt;/a&gt;</li><li>&lt;hr/&gt;</li><li>&lt;a href=&quot;springmvc/testGet&quot;&gt;</li></ul><p>取出</p><ul><li>SessionAttribute&lt;/a&gt;</li><li>&lt;hr/&gt;</li><li>&lt;a href=&quot;springmvc/testClean&quot;&gt;</li></ul><p>清除</p><p><code>SessionAttribute\\&lt;/a\\&gt;</code><strong>控制器中的代码：</strong></p><p>/**</p><ul><li><p>SessionAttribute 注解的使用</p></li><li><p>@author 黑马程序员</p></li><li><p>@Company <a href="http://www.ithiema.com" target="_blank" rel="noreferrer">http://www.ithiema.com</a></p></li><li><p>@Version 1.0 <em>/ @Controller(&quot;sessionAttributeController&quot;) 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训 @RequestMapping(&quot;/springmvc&quot;) @SessionAttributes(value ={&quot;username&quot;,&quot;password&quot;},types={Integer.class}) public class SessionAttributeController { /</em>*</p></li><li></li></ul><p><code>把数据存入</code> SessionAttribute</p><ul><li>@param model</li><li>@return</li><li>Model <code>是 </code>spring<code> 提供的一个接口，该接口有一个实现类</code> ExtendedModelMap</li><li></li></ul><p>该类继承了 <code>ModelMap</code>，而 <code>ModelMap</code> 就是 <code>LinkedHashMap</code> 子类</p><p>*/ @RequestMapping(&quot;/testPut&quot;) public String testPut(Model model){ model.addAttribute(&quot;username&quot;, &quot; <code>泰斯特</code> &quot;); model.addAttribute(&quot;password&quot;,&quot;123456&quot;); model.addAttribute(&quot;age&quot;, 31); // 跳转之前将数据保存到 <code>username</code>、<code>password</code> 和 <code>age</code> 中，因为注解<code>@SessionAttribute</code> 中有 这几个参数</p><p>return &quot;success&quot;; } @RequestMapping(&quot;/testGet&quot;) public String testGet(ModelMap model){ System.out.println(model.get(&quot;username&quot;)+&quot;;&quot;+model.get(&quot;password&quot;)+&quot;;&quot;+model.get(&quot;a ge&quot;)); return &quot;success&quot;; } @RequestMapping(&quot;/testClean&quot;) public String complete(SessionStatus sessionStatus){ sessionStatus.setComplete(); return &quot;success&quot;; } } <strong>运行结果：</strong></p></div>',1)])])}const q=t(s,[["render",r]]);export{g as __pageData,q as default};
